import { AuthStorage, ModelRegistry, SessionManager, Settings, createAgentSession } from "@oh-my-pi/pi-coding-agent";
const authStorage = await AuthStorage.create(":memory:");
const { session } = await createAgentSession({
  cwd: process.cwd(), agentDir: process.env.MARS_FIXTURE_AGENT_DIR,
  authStorage, modelRegistry: new ModelRegistry(authStorage),
  settings: Settings.isolated(), sessionManager: SessionManager.inMemory(),
  hasUI: false, disableExtensionDiscovery: true, skills: [], rules: [],
  contextFiles: [], noContextFiles: true, promptTemplates: [], slashCommands: [],
  toolNames: [], restrictToolNames: true, enableMCP: false, enableLsp: false,
  enableIrc: false, skipPythonPreflight: true, cacheWarming: false,
});
if (session.getActiveToolNames().length !== 0) throw new Error("unexpected executable tools");
if (session.sessionFile !== undefined) throw new Error("unexpected persistent session");
await session.dispose();
await authStorage.close();
